#include <stdio.h>
/* ex02：隐式链接分配——每块末尾存下一块的块号
 * 优点：无外部碎片、文件可随意增长；缺点：只能顺序访问，
 * 读第 k 块要沿着链走 k 次，每次都一次磁盘 I/O。*/
int main(void) {
    /* FAT 之外的隐式链接：块内末尾 4 字节存 next */
    int chain[] = {100, 205, 310, 411, 502, 620, 733, 840};
    int n = (int)(sizeof(chain) / sizeof(chain[0]));
    int seek_blocks = 1;   /* 每次取下一块算一次磁盘访问 */
    int total = 0;

    printf("块链: ");
    for (int i = 0; i < n; i++) printf("%d%s", chain[i], i == n - 1 ? "\n" : " -> ");

    printf("\n%-8s %-10s %-12s %s\n", "读第k块", "物理块", "累计磁盘访问", "说明");
    for (int k = 0; k < n; k++) {
        total += seek_blocks;
        printf("%-8d %-10d %-12d %s\n", k, chain[k], total, k == 0 ? "还需先读目录项拿到首块" : "沿链前进一步");
    }
    printf("\n读最后一个块共需 %d 次访问 -> 随机访问退化为 O(n)\n", total);
    printf("结论: 隐式链接适合「写一次读一遍」的日志文件，不适合随机读数据库。\n");
    return 0;
}
